#!/bin/sh
set -eu

VMSTAT=/proc/vmstat
PSI=/proc/pressure/memory
BOOT_ID=/proc/sys/kernel/random/boot_id

[ -r "$VMSTAT" ] && [ -r "$PSI" ] && [ -r "$BOOT_ID" ] || {
  echo "required procfs telemetry is unavailable" >&2
  exit 1
}

vm_fields=$(awk '
BEGIN {
  keys[1]="pgscan_direct"; keys[2]="pgscan_kswapd";
  keys[3]="pgsteal_direct"; keys[4]="pgsteal_kswapd";
  keys[5]="nr_file_pages"; keys[6]="nr_active_file";
  keys[7]="nr_inactive_file"; keys[8]="workingset_refault_file";
}
{ value[$1]=$2 }
END {
  for (i=1; i<=8; i++) if (!(keys[i] in value)) exit 2;
  for (i=1; i<=8; i++) printf "%s=%s ", keys[i], value[keys[i]];
}' "$VMSTAT") || {
  echo "required /proc/vmstat field is unavailable" >&2
  exit 1
}

psi_fields=$(awk '
$1=="some" || $1=="full" {
  lane=$1;
  for (i=2; i<=NF; i++) {
    split($i, pair, "=");
    value[lane "_" pair[1]]=pair[2];
  }
}
END {
  lanes[1]="some"; lanes[2]="full";
  names[1]="avg10"; names[2]="avg60"; names[3]="avg300"; names[4]="total";
  for (l=1; l<=2; l++) for (n=1; n<=4; n++) {
    key=lanes[l] "_" names[n];
    if (!(key in value)) exit 2;
    printf "psi_memory_%s=%s ", key, value[key];
  }
}' "$PSI") || {
  echo "malformed /proc/pressure/memory" >&2
  exit 1
}

printf 'sample_epoch=%s boot_id=%s page_size_bytes=%s %s%s\n' \
  "$(date +%s)" "$(cat "$BOOT_ID")" "$(getconf PAGESIZE)" \
  "$vm_fields" "$psi_fields"
